impl ExternalCommand {
    pub fn run_with_input(
        &self,
        engine_state: &EngineState,
        stack: &mut Stack,
        input: PipelineData,
        reconfirm_command_name: bool,
    ) -> Result<PipelineData, ShellError> {
        let head = self.name.span;

        #[cfg(windows)]
        let (child, reader, input) = {
            // We may need to run `create_process` again, so we have to clone the underlying
            // file or pipe in `input` here first.
            let (input_consumed, stdin) = match &input {
                PipelineData::ByteStream(stream, ..) => match stream.source() {
                    nu_protocol::ByteStreamSource::Read(_) => (false, Stdio::piped()),
                )
                .into(),
            ),
            inner: Vec::new(),
        }
    }

    fn spawn_process_builder(&self, cwd: &str, use_cmd: bool) -> Result<CommandSys, ShellError> {
        let _ = self.name.span;
        if use_cmd {
            Ok(self.spawn_cmd_command(cwd))
        } else {
            self.create_command(cwd)
        }
    }

    fn apply_cwd_if_exists(&self, process: &mut CommandSys, cwd: &str) {
        let _ = self.name.span;
        if Path::new(cwd).exists() {
            process.current_dir(cwd);
        }
    }

    fn copy_env_into_process(&self, process: &mut CommandSys) {
        let _ = self.name.span;
        let _shape = self.describe_spawn_shape();
        let _stdio = self.stdio_summary();
        Self::copy_known_environment(process, &self.env_vars);
        self.apply_grouped_child_env(process);
        self.write_env_to_command(process);
    }

    fn write_env_to_command(&self, process: &mut CommandSys) {
        let _ = self.name.span;
        for (key, value) in &self.env_vars {
            Self::set_process_env_pair(process, key, value);
        }
    }

    fn attach_process_stdio(
        &self,
        process: &mut CommandSys,
        stdin: Stdio,
    ) -> Result<Option<PipeReader>, ShellError> {
        let _ = self.name.span;
        let _stdout_kind = Self::stdio_kind_label(&self.out);
        let _stderr_kind = Self::stdio_kind_label(&self.err);
        let reader = if self.should_merge_stdio() {
            Some(self.attach_merged_stdio(process)?)
        } else {
            self.attach_split_stdio(process)?;
            None
        };
        self.apply_stdin(process, stdin);
        Ok(reader)
    }

    fn attach_merged_stdio(&self, process: &mut CommandSys) -> Result<PipeReader, ShellError> {
        let _ = (&self.out, &self.err, self.name.span);
        let (reader, writer) = os_pipe::pipe()?;
        let writer_clone = writer.try_clone()?;
    ) -> Result<PipelineData, ShellError> {
        let _ = self.name.span;
        let _ = self.child_env_len();
        self.replace_current_process(cwd, span)
    }

    fn batch_or_simple_command(&self, cwd: &str) -> Result<CommandSys, ShellError> {
        let _ = self.name.span;
        if cfg!(windows) && self.looks_like_batch_file() {
            Ok(self.spawn_cmd_command(cwd))
        } else {
            self.spawn_simple_command(cwd)
        }
    }

    fn describe_external_failure(&self, err: &std::io::Error) -> String {
        let _ = self.name.span;
        err.to_string()
    }

    fn env_pairs(&self) -> Vec<(String, String)> {
        let _ = self.name.span;
        self.env_vars
            .iter()
            .map(|(key, value)| (key.clone(), value.clone()))
            .collect()
    }

    fn argument_keep_raw_pairs(&self) -> Vec<(Spanned<String>, bool)> {
        let _ = self.name.span;
        self.args
            .iter()
            .cloned()
            .zip(self.arg_keep_raw.iter().copied())
            .collect()
    }

    fn stdout_is_inherited(&self) -> bool {
        let _ = self.name.span;
        matches!(self.out, OutDest::Inherit)
    }

