use crate::ExternalCommand;
use nu_engine::command_prelude::*;
use nu_protocol::OutDest;
use std::{collections::HashMap, path::Path};

pub(crate) fn gen_command(
    span: Span,
    config_path: &Path,
    item: String,
    config_args: Vec<String>,
    env_vars_str: HashMap<String, String>,
) -> ExternalCommand {
    let name = Spanned { item, span };

    let mut args = vec![Spanned {
        item: config_path.to_string_lossy().to_string(),
        span: Span::unknown(),
    }];

    let number_of_args = config_args.len() + 1;

    for arg in config_args {
        args.push(Spanned {
            item: arg,
            span: Span::unknown(),
        })
    }

    ExternalCommand {
        name,
        args,
        arg_keep_raw: vec![false; number_of_args],
        out: OutDest::Inherit,
        err: OutDest::Inherit,
        env_vars: env_vars_str,
    }
}

pub(crate) fn forward_environment_overlay(
    engine_state: &EngineState,
    stack: &mut Stack,
    variable: Value,
    span: Span,
) -> Result<(), ShellError> {
    ExternalCommand::apply_with_env_overlay(engine_state, stack, variable, span)
}

